  replacementAgeYears: 12,
  repeatWindowDays: 180,
  membershipOverdueDays: 30,
  estimateStaleDays: 7,
  capacityLookaheadDays: 2,
  afterHoursStartHour: 17,
  maxItemsPerSection: 10,
  historyDays: 90,
};
const HOUR = 3600000;
