  blankSkill.sort(sortId);
  missingZone.sort(sortId);
  autoModeExclusionRisk.sort(sortId);
  const flaggedIds = {};
  agedUnassigned.concat(blankSkill, missingZone, autoModeExclusionRisk).forEach(function (r) { flaggedIds[r.jobId] = true; });
